{
  "items": [
    {
      "name": "Set.mem_image2_of_mem",
      "module_name": "Mathlib.Data.Set.Operations",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} {γ : Type w} {f : α → β → γ} {s : Set α} {t : Set β} {a : α} {b : β},\n  a ∈ s → b ∈ t → f a b ∈ Set.image2 f s t"
    },
    {
      "name": "Set.mem_image2",
      "module_name": "Mathlib.Data.Set.Operations",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} {γ : Type w} {f : α → β → γ} {s : Set α} {t : Set β} {c : γ},\n  c ∈ Set.image2 f s t ↔ ∃ a, a ∈ s ∧ ∃ b, b ∈ t ∧ f a b = c"
    },
    {
      "name": "Set.image2",
      "module_name": "Mathlib.Data.Set.Operations",
      "kind": "definition",
      "type": "{α : Type u} → {β : Type v} → {γ : Type w} → (α → β → γ) → Set α → Set β → Set γ"
    },
    {
      "name": "Finset.mem_image₂",
      "module_name": "Mathlib.Data.Finset.NAry",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_3} {γ : Type u_5} [inst : DecidableEq γ] {f : α → β → γ} {s : Finset α} {t : Finset β}\n  {c : γ}, c ∈ Finset.image₂ f s t ↔ ∃ a ∈ s, ∃ b ∈ t, f a b = c"
    },
    {
      "name": "Set.exists_mem_image2",
      "module_name": "Mathlib.Data.Set.NAry",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_3} {γ : Type u_5} {f : α → β → γ} {s : Set α} {t : Set β} {p : γ → Prop},\n  (∃ z, z ∈ Set.image2 f s t ∧ p z) ↔ ∃ x, x ∈ s ∧ ∃ y, y ∈ t ∧ p (f x y)"
    },
    {
      "name": "Set.image",
      "module_name": "Mathlib.Data.Set.Defs",
      "kind": "definition",
      "type": "{α : Type u} → {β : Type v} → (α → β) → Set α → Set β"
    }
  ]
}
